head.script:
scwin.gVar = {
    "cID" : ""
}



scwin.onpageload = function () {
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }    

    // 조건 설정
    let cID = scwin.gVar["cID"];

    // comp 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    // tableLayout = xf:group tagname="table" + class="w2tb" (pluginName group)
    //  - createBasicTableLayout 은 빈 cID 를 target1 로 고정하므로 ID 미설정 검증을 위해 직접 생성
    //  - dynamicCreate 는 자식 태그를 생성하지 않으므로 table 생성 후 공통 appendTableLayoutRows 로 colgroup/tr/th/td 생성 (하위 id 는 빈값 → 엔진 자동 id)
    strTarget += '<xf:group ' + strNameSpace + ' tagname="table" class="w2tb tbl" style="width:600px;"></xf:group>';

    scwin.target1 = await $p.dynamicCreate(
        cID,
        "group",
        strTarget,
        grp_comp
    );

    await $c.gcm.appendTableLayoutRows(scwin.target1, '', {});
}
